const INDEX = "<!DOCTYPE html><html><head><meta charset=\"UTF-8\"><title>QRON Brand Demos</title><style>body{font-family:Inter,sans-serif;background:#0a0a0a;color:#e0e0e0;padding:40px;max-width:600px;margin:0 auto}h1{color:#d4af37;margin-bottom:24px}a{color:#d4af37;display:block;padding:12px 0;font-size:18px;text-decoration:none;border-bottom:1px solid #222}a:hover{color:#fff}</style></head><body><h1>QRON Authentication Previews</h1><a href=\"/common-citizen\">common-citizen</a><a href=\"/house-of-dank\">house-of-dank</a><a href=\"/jars-cannabis\">jars-cannabis</a><a href=\"/lion-labs\">lion-labs</a><a href=\"/skymint\">skymint</a></body></html>";
export default {
  async fetch(req) {
    const url = new URL(req.url);
    const slug = url.pathname.replace(/^\//, '').replace(/\/$/, '');
    const headers = { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public, max-age=3600' };
    if (!slug || slug === 'index') return new Response(INDEX, { headers });
    if (PAGES[slug]) return new Response(PAGES[slug], { headers });
    return new Response('Not found', { status: 404, headers: { 'Content-Type': 'text/plain' } });
  }
};
